import{c as e,J as a,h as r,k as s}from"./chunks/framework.WgZQdPFo.js";const p=JSON.parse('{"title":"Analytics & Currency Basket","description":"In-depth wealth analytics, long-term Net Worth dynamics, currency basket diversification, and asset class distributions.","frontmatter":{"title":"Analytics & Currency Basket","description":"In-depth wealth analytics, long-term Net Worth dynamics, currency basket diversification, and asset class distributions.","order":22},"headers":[],"relativePath":"docs/spaces/moy-kapital/analytics.md","filePath":"docs/spaces/moy-kapital/analytics.md"}'),i={name:"docs/spaces/moy-kapital/analytics.md"};function o(n,t,c,l,d,u){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="analytics-currency-basket" tabindex="-1">Analytics &amp; Currency Basket <a class="header-anchor" href="#analytics-currency-basket" aria-label="Permalink to &quot;Analytics &amp; Currency Basket&quot;">​</a></h1><p>The <strong>Capital Analytics</strong> tab and the <strong>Statistics</strong> widget offer a strategic overview of your financial trajectory. Here, the focus shifts away from day-to-day cash balances to multi-year horizons: is your family&#39;s real wealth growing year-over-year, and how securely is your capital protected against economic and currency shocks?</p><hr><h2 id="multi-series-wealth-growth-chart" tabindex="-1">Multi-Series Wealth Growth Chart <a class="header-anchor" href="#multi-series-wealth-growth-chart" aria-label="Permalink to &quot;Multi-Series Wealth Growth Chart&quot;">​</a></h2><p>The center of the screen features an interactive multi-series chart tracking historical trends month-by-month:</p><ul><li>🟢 <strong>Consolidated Net Worth:</strong> the primary trajectory of your consolidated wealth.</li><li>🟣 <strong>Enterprise Capital:</strong> combined asset valuation across all connected workshops (cash + materials + inventory).</li><li>🔵 <strong>Net Profit:</strong> operational performance of production units after direct and overhead expenses.</li><li>🟡 <strong>Revenue:</strong> gross customer receipts collected.</li></ul><div class="info custom-block"><p class="custom-block-title">Preserving History of Archived Workspaces</p><p>If you close or sell a subsidiary business and delete its workspace from the program, its historical contribution is never erased from the timeline. OmniCraft ERP permanently preserves monthly snapshots so your multi-year Net Worth trajectory remains unbroken.</p></div><hr><h2 id="currency-basket-allocation" tabindex="-1">Currency Basket Allocation <a class="header-anchor" href="#currency-basket-allocation" aria-label="Permalink to &quot;Currency Basket Allocation&quot;">​</a></h2><p>To protect capital against devaluations and inflation, OmniCraft ERP visualizes your <strong>Currency Basket</strong>:</p><ul><li><strong>Multi-Segment Stacked Bar:</strong> shows the exact percentage ratio of currencies held across liquid accounts and investments (e.g., $60%$ USD, $25%$ EUR, $15%$ USDT).</li><li><strong>Currency Breakdown List:</strong> comprehensive breakdown for each currency specifying native amounts, base currency equivalent, and portfolio share.</li><li><strong>Standardized International Names:</strong> currencies are displayed with accurate localized titles based on the Unicode Babel standard.</li></ul><div class="tip custom-block"><p class="custom-block-title">Golden Rule of Craft Diversification</p><p>Maintain an operational buffer (covering 2–3 months of workshop expenses) in the currency used by your primary leather and hardware suppliers. Allocate surplus investment capital across stable currencies and durable physical assets.</p></div><hr><h2 id="capital-statistics-widget" tabindex="-1">Capital Statistics Widget <a class="header-anchor" href="#capital-statistics-widget" aria-label="Permalink to &quot;Capital Statistics Widget&quot;">​</a></h2><p>Clicking the <strong>&quot;📊 Statistics&quot;</strong> button in the top toolbar opens a dedicated analytical view.</p><p>Depending on your preference, it renders in one of two modes:</p><ol><li><strong>Side Drawer:</strong> slides in smoothly from the right without covering main tables, allowing you to audit account lists and currency distributions simultaneously.</li><li><strong>Modal Dialog:</strong> centered pop-up window for focused balance audits.</li></ol><p>The display mode can be selected in the <strong>&quot;⚙️ Workspace Settings&quot;</strong> dialog.</p>',18)])])}const y=e(i,[["render",o]]);export{p as __pageData,y as default};
